function validate([m, n, horizontalCut, verticalCut]) {
  if (m < 1 || m > 100000 || n < 1 || n > 100000) return 'm and n are between 1 and 10^5.';
  if (horizontalCut.length !== m - 1) return 'horizontalCut needs exactly m - 1 costs.';
  if (verticalCut.length !== n - 1) return 'verticalCut needs exactly n - 1 costs.';
  if (horizontalCut.some(v => v < 1 || v > 1000) || verticalCut.some(v => v < 1 || v > 1000)) return 'Every cut costs between 1 and 1000.';
  return null;
}

