function minimumCost(m, n, horizontalCut, verticalCut) {
  // Try every first cut of every piece: the cheapest way to finish rows [top, bottom) x columns [left, right).
  const memo = new Map();
  const best = (top, bottom, left, right) => {
    if (bottom - top === 1 && right - left === 1) return 0;
    const key = top + ',' + bottom + ',' + left + ',' + right;
    if (memo.has(key)) return memo.get(key);
    let cheapest = Infinity;
    for (let line = top; line < bottom - 1; line++)
      cheapest = Math.min(cheapest, horizontalCut[line] + best(top, line + 1, left, right) + best(line + 1, bottom, left, right));
    for (let line = left; line < right - 1; line++)
      cheapest = Math.min(cheapest, verticalCut[line] + best(top, bottom, left, line + 1) + best(top, bottom, line + 1, right));
    memo.set(key, cheapest);
    return cheapest;
  };
  return best(0, m, 0, n);
}

