function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'large' ? int(1500, 2001) : int(1, 5);
  const n = size === 'large' ? int(1500, 2001) : int(1, 5);
  // Small inputs sometimes use costs 1 to 3 so that ties between lines are common.
  const top = size === 'large' || rand() < 0.5 ? 1000 : 3;
  const costs = (count) => Array.from({ length: count }, () => int(1, top));
  return [m, n, costs(m - 1), costs(n - 1)];
}
